import simplejson
import os
import logging
import decimal
import collections

from openpyxl import load_workbook

from taf.ul.bts_kpi_report_generator.generator.ExcelFormulaTranslator import ExcelFormulaTranslator


class GenerateJSON:
    """
    Class for generating JSON files containing resulting values .
    """
    def __init__(self, path_dir, skip_beg, skip_end, report_name):
        self.__json_data = collections.OrderedDict()
        self.__translator = ExcelFormulaTranslator()
        self.__number_of_measurements = None
        self.__path_dir = path_dir
        self.__skip_beg = skip_beg
        self.__skip_end = skip_end

        wb = load_workbook(os.path.join(self.__path_dir, report_name + '.xlsx'))
        self.__result_sheet = wb["RESULTS"]
        log_format = "%(levelname)s %(asctime)s - %(message)s"
        logging.basicConfig(level=logging.DEBUG, filemode='w', format=log_format)

    def __calculate_average(self, name, object_type):
        """
        Calculates average value from calculated values of each object

        :param name: KPI name
        :param object_type: Object name

        :return: Calculated average value .
        """

        sum_value = decimal.Decimal()
        NA_cells = 0

        listed_measurements = list(self.__json_data[name][object_type]["Data"].values())

        for measurement_number in range(self.__skip_beg, self.__number_of_measurements - self.__skip_end):
            if listed_measurements[measurement_number] == 'NA':
                NA_cells += 1
            else:
                sum_value += decimal.Decimal(listed_measurements[measurement_number])

        sum_value = decimal.Decimal(sum_value).quantize(decimal.Decimal("0.00"))

        return decimal.Decimal(sum_value / (self.__number_of_measurements - self.__skip_beg
                                            - self.__skip_end - NA_cells)).quantize(decimal.Decimal("0.00"))

    def __calculate_value(self, name, names_row, object_type):
        """
        Calculate values for each test

        :param name: name of a KPI
        :param names_row: Row containing all KPI objects
        :param object_type: Type of current object

        :return: None
        """
        self.__json_data[name][object_type].update({"Data": collections.OrderedDict()})
        for rows in range(2, self.__result_sheet.max_row + 1):
            try:
                formula = self.__result_sheet.cell(row=rows, column=names_row).value
                if str(formula).replace(".", "").isdigit():
                    returned_value = formula
                else:
                    returned_value = self.__translator.calculate_formula(formula)
                self.__json_data[name][object_type]["Data"].update({str(self.__result_sheet.cell(row=rows, column=1).value): returned_value})
            except Exception as exc:
                exc_str = str(exc).lower().replace(" ", "")
                if "na" not in exc_str and "division" not in exc_str and "0/0" not in exc_str:
                    whole_name = self.__result_sheet.cell(row=1, column=names_row).value
                    logging.warning(
                        "Unexpected error occurred {} when calculating average of {}".format(exc, whole_name))
                self.__json_data[name][object_type]["Data"].update({str(self.__result_sheet.cell(row=rows, column=1).value): 'NA'})

    def generate_JSON(self):
        """
        Generates mentioned JSON files

        :return: None
        """
        previous_name = ''
        self.__number_of_measurements = self.__result_sheet.max_row - 1
        for names_row in range(2, self.__result_sheet.max_column + 1):
            whole_name = self.__result_sheet.cell(row=1, column=names_row).value
            last_space_index = whole_name.find(' ')
            name = whole_name[:last_space_index]
            object_type = whole_name[last_space_index + 1:]
            if name != previous_name:
                self.__json_data.update({name: {object_type: collections.OrderedDict()}})
            else:
                self.__json_data[name].update({object_type: collections.OrderedDict()})
            previous_name = name
            self.__calculate_value(name, names_row, object_type)
            try:
                self.__json_data[name][object_type].update({"Average": self.__calculate_average(name, object_type)})
            except Exception as exc:
                exc_str = str(exc).lower().replace(" ", "")
                if "na" not in exc_str and "division" not in exc_str and "0/0" not in exc_str:
                    logging.warning("Unexpected error occurred {} when calculating average of {}".format(exc, whole_name))
                self.__json_data[name][object_type].update({"Average": "NA"})

        with open(os.path.join(self.__path_dir, 'result.json'), 'w') as jf:
            simplejson.dump(self.__json_data, jf, use_decimal=True)
        return self.__json_data
